// PROBE 1 — run against TODAY's game/neon.js (no fix).
// Demonstrates the reported symptom on the current code: step() ignores bricks.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { createState, step, collides, PADDLE_Y, BALL_R } from '../game/neon.js';

// One brick at [100,172]x[200,220]; ball centered at x=136, below the brick,
// moving straight up at level-1 speed.
function stateWithBrick(level = 1) {
  const state = createState(level);
  state.bricks = [{ x: 100, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 }];
  state.ball = { x: 136, y: 227.5, r: BALL_R, vx: 0, vy: -260 };
  return state;
}

// D1 — the missing bounce.
test('D1: ball moving up into the bottom face bounces back down and breaks the brick', () => {
  const state = stateWithBrick(1);
  step(state, 1 / 60);
  assert.equal(state.bricks[0].alive, false, 'brick must be broken');
  assert.ok(state.ball.vy > 0, 'vertical velocity must flip DOWN (bounce)');
  assert.ok(state.ball.y + state.ball.r > 220, 'ball must be below the brick');
});

// D2 — the sticky residue: overlapping at end-of-step must be resolved (pushed out).
test('D2: after the bounce the ball must not still overlap the brick', () => {
  const state = stateWithBrick(1);
  state.ball.y = 224; // already penetrating the bottom face (box [217,231])
  step(state, 1 / 60);
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball must be pushed out of the brick');
});

// D3 — seam: overlapping two side-by-side bricks at once must flip vx exactly once.
test('D3: ball overlapping two bricks at a grid seam bounces once, not twice', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 },
    { x: 180, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 },
  ];
  state.ball = { x: 176, y: 210, r: BALL_R, vx: 200, vy: 0 }; // box [169,183] straddles the 8px gap
  step(state, 1e-4);
  assert.equal(state.ball.vx, -200, 'exactly one horizontal flip: ball must bounce off the seam');
});

// D5 — tunneling: level 6, dt capped at 0.05 => step 35.5px > 34px (brick h 20 + diameter 14).
test('D5: level-6 ball cannot jump a brick in one frame (no tunneling)', () => {
  const state = stateWithBrick(6);
  state.ball.vy = -710;
  step(state, 0.05); // 710 * 0.05 = 35.5 px — more than the 34 px it takes to cross a brick
  assert.equal(state.bricks[0].alive, false, 'brick must be hit even though no end-position overlaps');
  assert.ok(state.ball.vy > 0, 'ball must bounce down');
});

// D6 — paddle tunneling: level 5, 620*0.05 = 31px > 26px (paddle h 12 + diameter 14).
test('D6: fast ball cannot pass through the paddle', () => {
  const state = createState(5);
  state.ball = { x: 320, y: 440.5, r: BALL_R, vx: 0, vy: 620 };
  assert.ok(state.ball.y + BALL_R < PADDLE_Y, 'bottom edge starts above the paddle');
  const lost = step(state, 0.05);
  assert.equal(lost, false, 'ball must not be lost');
  assert.ok(state.ball.vy < 0, 'ball must bounce up');
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y, 'ball must come back out above the paddle');
});

// PROBE 2 — the NAIVE correction: flip a velocity component on overlap, per brick,
// without pushing the ball out and without deduplicating overlapping bricks.
// These are the "corrections naïves" each test must refuse.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { createState, collides, PADDLE_Y, BALL_R } from '../game/neon.js';

// Naive #1: flip vy on any overlap (the head-on correction) — no push-out.
// Naive #2: flip per brick, two overlapping bricks => two flips (seam).
// Naive #3: flip the axis by penetration, but resolve each brick separately and never push out.
function naiveStep(state, dt) {
  const { ball } = state;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      brick.alive = false;
      ball.vy = -ball.vy; // always flip vy: the head-on correction
    }
  }
  return ball.y - ball.r > 480;
}

function stateWithBrick(level = 1) {
  const state = createState(level);
  state.bricks = [{ x: 100, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 }];
  state.ball = { x: 136, y: 227.5, r: BALL_R, vx: 0, vy: -260 };
  return state;
}

test('NAIVE-D1: ball bounces off the bottom face and breaks the brick', () => {
  const state = stateWithBrick(1);
  naiveStep(state, 1 / 60);
  assert.equal(state.bricks[0].alive, false);
  assert.ok(state.ball.vy > 0, 'vertical velocity must flip DOWN');
  assert.ok(state.ball.y + state.ball.r > 220, 'ball must end below the brick');
});

test('NAIVE-D2: two consecutive passes must not re-invert the velocity (sticky)', () => {
  const state = stateWithBrick(1);
  state.ball.y = 224; // penetrating the bottom face (box [217,231])
  naiveStep(state, 1 / 60); // flips vy to +260 but leaves the ball inside
  naiveStep(state, 1 / 60); // still overlapping -> flips AGAIN, back into the brick
  assert.ok(state.ball.vy > 0, 'velocity must still point away from the brick after two passes');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball must be outside after two passes');
});

test('NAIVE-D3: seam — two overlapping bricks must not cancel the flip', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 },
    { x: 180, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 },
  ];
  state.ball = { x: 176, y: 210, r: BALL_R, vx: 200, vy: 0 };
  naiveStep(state, 1e-4);
  assert.equal(state.ball.vx, -200, 'exactly one flip: the ball bounces off the seam');
});

test('NAIVE-D4: side hit flips vx, not vy', () => {
  const state = createState(1);
  state.bricks = [{ x: 100, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 }];
  state.ball = { x: 94, y: 210, r: BALL_R, vx: 150, vy: 100 }; // box [87,101]: ox=1 < oy=14
  naiveStep(state, 1e-4);
  assert.equal(state.ball.vx, -150, 'vx must flip (side face hit)');
  assert.equal(state.ball.vy, 100, 'vy must be untouched');
});

test('NAIVE-D4-corner: equal penetrations flip BOTH axes', () => {
  const state = createState(1);
  state.bricks = [{ x: 100, y: 200, w: 72, h: 20, row: 4, alive: true, points: 10 }];
  state.ball = { x: 102, y: 218, r: BALL_R, vx: 100, vy: -300 }; // box [95,109]x[211,225]: ox=oy=9
  naiveStep(state, 1e-4);
  assert.equal(state.ball.vx, -100, 'corner hit must flip vx');
  assert.equal(state.ball.vy, 300, 'corner hit must flip vy');
});

