// Naive #1: flip vy on any overlap (the head-on correction) — no push-out.
// Naive #2: resolve every overlapping brick independently (per-brick flip + push-out).
function naiveStep(state, dt) {
  const { ball } = state;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      brick.alive = false;
      ball.vy = -ball.vy; // always flip vy: the head-on correction
    }
  }
  return ball.y - ball.r > 480;
}

// Naive #2: per-brick min-penetration flip WITH push-out — but each brick handled
// independently, so two overlapping bricks get resolved twice in the same pass.
function naivePerBrickStep(state, dt) {
  const { ball } = state;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const ox = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
    const oy = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
    if (ox <= 0 || oy <= 0) continue;
    brick.alive = false;
    if (ox < oy) {
      ball.vx = -ball.vx;
      ball.x += ball.vx > 0 ? ox + 0.01 : -(ox + 0.01);
    } else if (oy < ox) {
      ball.vy = -ball.vy;
      ball.y += ball.vy > 0 ? oy + 0.01 : -(oy + 0.01);
    } else {
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    }
  }
  return ball.y - ball.r > 480;
}

