// PROBE 3 — FINAL FORM of the defect tests, as they will live in the suite.
// Imports `resolveBricks`, which does not exist in game/neon.js today:
// this file must fail to load (the red of today for D2/D3/D4).
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { createState, step, collides, resolveBricks, PADDLE_Y, BALL_R } from '../game/neon.js';

function brickState(x, y, w = 72, h = 20, points = 10) {
  return { x, y, w, h, row: 4, alive: true, points };
}

// --- D1/D5/D6: integration through step() -----------------------------------

test('D1: ball moving up into the bottom face bounces back down and breaks the brick', () => {
  const state = createState(1);
  state.bricks = [brickState(100, 200)];
  state.ball = { x: 136, y: 227.5, r: BALL_R, vx: 0, vy: -260 };
  step(state, 1 / 60);
  assert.equal(state.bricks[0].alive, false);
  assert.equal(state.ball.vy, 260);
  assert.equal(collides(state.ball, state.bricks[0]), false);
  assert.equal(state.score, 15); // 10 pts * 1.5 (combo 1), awarded once
  assert.equal(state.combo, 1);
});

test('D5: level-6 ball cannot jump a brick in one frame (no tunneling)', () => {
  const state = createState(6);
  state.bricks = [brickState(100, 200)];
  state.ball = { x: 136, y: 227.5, r: BALL_R, vx: 0, vy: -710 };
  step(state, 0.05); // 710 * 0.05 = 35.5 px > 34 px (brick h 20 + diameter 14)
  assert.equal(state.bricks[0].alive, false, 'brick must be hit');
  assert.ok(state.ball.vy > 0, 'ball must bounce down');
  assert.ok(state.ball.y + state.ball.r > 220, 'ball must end below the brick');
});

test('D6: fast ball cannot pass through the paddle', () => {
  const state = createState(5);
  state.ball = { x: 320, y: 440.5, r: BALL_R, vx: 0, vy: 620 };
  assert.ok(state.ball.y + BALL_R < PADDLE_Y, 'bottom edge starts above the paddle');
  const lost = step(state, 0.05); // 620 * 0.05 = 31 px > 26 px (paddle h 12 + diameter 14)
  assert.equal(lost, false, 'ball must not be lost');
  assert.equal(state.ball.vy, -620, 'ball must bounce up');
  assert.equal(state.ball.y, PADDLE_Y - BALL_R, 'ball must leave from the top of the paddle');
});

// --- D2/D3/D4: unit through resolveBricks ------------------------------------

test('D2: the bounce pushes the ball out, and a second pass does not re-invert', () => {
  const state = createState(1);
  state.bricks = [brickState(100, 200)];
  state.ball = { x: 136, y: 224, r: BALL_R, vx: 0, vy: -300 }; // box [217,231]: oy=3, ox=14
  resolveBricks(state);
  assert.equal(state.ball.vy, 300, 'vertical velocity flipped away from the brick');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball pushed out of the brick');
  resolveBricks(state); // second pass: still touching? must NOT flip again
  assert.equal(state.ball.vy, 300, 'no re-inversion on a second pass');
});

test('D3: two overlapping bricks at a seam are resolved once, not twice', () => {
  const state = createState(1);
  state.bricks = [brickState(100, 200), brickState(180, 200)];
  state.ball = { x: 177, y: 210, r: BALL_R, vx: 200, vy: 0 }; // box [170,184]: ox_A=2, ox_B=4
  resolveBricks(state);
  assert.equal(state.ball.vx, -200, 'exactly one horizontal flip: the seam bounces the ball');
  assert.equal(state.ball.vy, 0, 'vertical velocity untouched');
});

test('D4-side: a side hit flips vx and leaves vy alone', () => {
  const state = createState(1);
  state.bricks = [brickState(100, 200)];
  state.ball = { x: 94, y: 210, r: BALL_R, vx: 150, vy: 100 }; // box [87,101]x[203,217]: ox=1, oy=14
  resolveBricks(state);
  assert.equal(state.ball.vx, -150, 'vx flipped (left face hit)');
  assert.equal(state.ball.vy, 100, 'vy untouched');
  assert.equal(collides(state.ball, state.bricks[0]), false);
});

test('D4-face: a top/bottom face hit flips vy and leaves vx alone', () => {
  const state = createState(1);
  state.bricks = [brickState(100, 200)];
  state.ball = { x: 136, y: 224, r: BALL_R, vx: 50, vy: -300 }; // box [217,231]: oy=3, ox=14
  resolveBricks(state);
  assert.equal(state.ball.vy, 300, 'vy flipped (bottom face hit)');
  assert.equal(state.ball.vx, 50, 'vx untouched');
  assert.equal(collides(state.ball, state.bricks[0]), false);
});

test('D4-corner: equal penetrations flip BOTH axes', () => {
  const state = createState(1);
  state.bricks = [brickState(100, 200)];
  state.ball = { x: 102, y: 218, r: BALL_R, vx: 100, vy: -300 }; // box [95,109]x[211,225]: ox=oy=9
  resolveBricks(state);
  assert.equal(state.ball.vx, -100, 'corner flips vx');
  assert.equal(state.ball.vy, 300, 'corner flips vy');
  assert.equal(collides(state.ball, state.bricks[0]), false);
});

