}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face is decided in resolveBricks() by the smallest
// penetration axis.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Brick collision resolution (pure, testable) ---------------------------

// Maximum distance the ball may travel in one physics sub-step. Kept below
// the ball's radius so the FIRST contact with any face is always shallow:
// the face choice (smallest penetration) stays unambiguous, and no obstacle
// can be jumped in a single sub-step (a brick is 20+14 px thick, the paddle
// 12+14 px — both far above 7 px).
const MAX_SUBSTEP = BALL_R;

// Small push added to the penetration so the ball ends up strictly OUTSIDE
// the brick: the next pass sees no overlap and cannot re-invert the velocity.
const PUSH_EPS = 0.01;

// Bounces the ball off the live brick it overlaps and destroys the brick.
// The hit face is the axis of the smallest penetration (ox vs oy); equal
// penetrations mean a corner hit and BOTH axes are inverted. The ball is
// pushed back out of the brick along the axis it now travels on, so it never
// re-overlaps on a later pass.
//
// The brick resolved is the one with the SMALLEST penetration over ALL the
// bricks the ball overlaps: two bricks touched at a grid seam (the ball's
// diameter 14 px is wider than BRICK_GAP 8 px) must not each invert the
// velocity — two flips on the same axis cancel out and the ball would sail
// through the seam. Returns true if a brick was hit.
export function resolveBricks(state) {
  const { ball } = state;

  // Find the overlapping brick the ball has penetrated the least.
  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const ox = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
    const oy = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
    if (ox <= 0 || oy <= 0) continue;
    const penetration = Math.min(ox, oy);
    if (!best || penetration < best.penetration) {
      best = { brick, ox, oy, penetration };
    }
  }
  if (!best) return false;

  const { brick, ox, oy } = best;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  if (ox < oy) {
    // Side face: bounce horizontally, push the ball sideways out.
    ball.vx = -ball.vx;
    ball.x += ball.vx > 0 ? ox + PUSH_EPS : -(ox + PUSH_EPS);
  } else if (oy < ox) {
    // Top/bottom face: bounce vertically, push the ball out.
    ball.vy = -ball.vy;
    ball.y += ball.vy > 0 ? oy + PUSH_EPS : -(oy + PUSH_EPS);
  } else {
    // Corner: equal penetrations on both axes — invert BOTH velocities.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x += ball.vx > 0 ? ox + PUSH_EPS : -(ox + PUSH_EPS);
    ball.y += ball.vy > 0 ? oy + PUSH_EPS : -(oy + PUSH_EPS);
  }
  return true;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
//
// The step is split into sub-steps of at most MAX_SUBSTEP px so that a fast
// ball (level >= 6, dt capped at 0.05 s) cannot tunnel through a brick or the
// paddle between two discrete tests. The paddle bounce triggers on the
// CROSSING of the paddle's top line, not on landing inside its 12 px band:
// a band check alone would let a fast ball jump the paddle entirely.
export function step(state, dt) {
  const { ball, paddle } = state;
  const speed = Math.hypot(ball.vx, ball.vy);
  const n = Math.max(1, Math.ceil((speed * dt) / MAX_SUBSTEP));
  const subDt = dt / n;

  for (let i = 0; i < n; i++) {
    const prevBottom = ball.y + ball.r;
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle: bounce the instant the bottom edge crosses the paddle's top line
    // while the ball is still coming from above and is within the paddle width.
    if (
      ball.vy > 0 &&
      prevBottom < paddle.y &&
      ball.y + ball.r >= paddle.y &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    resolveBricks(state);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (canvas only — all logic lives in step()/resolveBricks()) ----

// Main render loop: draws bricks, paddle, ball and HUD. No game logic here.

